function findIn(parent, pred){
  const res=[];
  function walk(node){
    if(pred(node)) res.push(node);
    if('children'in node) node.children.forEach(walk);
  }
  walk(parent);
  return res;
}

function byText(frame, txt){
  return findIn(frame, n=>n.type==='TEXT' && n.characters===txt);
