      if(a && a.type==='UPDATE_PRESENCE') return 'PRESENCE';
      return a?a.type:'?';
    }).join(' , '));
  }
  if('children' in node){
    node.children.forEach(c=>collectReactions(c, path+'/'+c.name, out));
  }
}

