function addReaction(node, destName, trigger='ON_CLICK'){
  if(!byName[destName] || !node) return 'MISS';
  const reactions = JSON.parse(JSON.stringify(node.reactions||[]));
  const has = reactions.some(r=>{const a=r.action; return a && a.type==='NODE' && a.destinationId===byName[destName].id;});
  if(has) return 'EXISTS';
  reactions.push({trigger, action:{type:'NODE', destinationId:byName[destName].id, navigation:'SCREEN', transition:{type:'SMART_ANIMATE', easing:{type:'EASE_IN_OUT', duration:400}}}});
  node.reactions = reactions;
  return 'ADD';
}

